<?php require __DIR__.'/includes/header.php';$p=dev_require_project($projectId);$error='';
if(isset($_GET['complete'])){$id=(int)$_GET['complete'];db()->prepare("UPDATE construction_tasks SET status='Complete',completed_at=NOW(),updated_at=NOW() WHERE id=? AND construction_project_id=?")->execute([$id,$projectId]);dev_activity($projectId,'task_completed','Task marked complete.','task',$id);header("Location: tasks.php?project_id=$projectId");exit;}
if(isset($_GET['reopen'])){$id=(int)$_GET['reopen'];db()->prepare("UPDATE construction_tasks SET status='Open',completed_at=NULL,updated_at=NOW() WHERE id=? AND construction_project_id=?")->execute([$id,$projectId]);header("Location: tasks.php?project_id=$projectId");exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!csrf_check((string)$_POST['csrf']))throw new RuntimeException('Session expired.');$action=$_POST['action']??'add';if($action==='comment'){$id=(int)$_POST['task_id'];$text=trim((string)$_POST['comment_text']);if($text!=='')db()->prepare('INSERT INTO construction_task_comments(task_id,admin_user_id,comment_text,created_at) VALUES(?,?,?,NOW())')->execute([$id,$user['id'],$text]);header("Location: tasks.php?project_id=$projectId&view=$id");exit;}$title=trim((string)$_POST['title']);if($title==='')throw new RuntimeException('Task title is required.');$s=db()->prepare('INSERT INTO construction_tasks(construction_project_id,construction_building_id,title,description,task_type,priority,status,due_date,assigned_admin_user_id,assigned_company_id,created_by_admin_user_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$s->execute([$projectId,($_POST['construction_building_id']??'')?:null,$title,trim((string)$_POST['description']),$_POST['task_type'],$_POST['priority'],'Open',$_POST['due_date']?:null,$_POST['assigned_admin_user_id']?:null,$_POST['assigned_company_id']?:null,$user['id']]);$id=(int)db()->lastInsertId();$helper=db()->prepare('INSERT IGNORE INTO construction_task_helpers(task_id,admin_user_id,created_at) VALUES(?,?,NOW())');foreach((array)($_POST['helper_ids']??[]) as $hid){if((int)$hid)$helper->execute([$id,(int)$hid]);}dev_activity($projectId,'task_created','Task created: '.$title,'task',$id);header("Location: tasks.php?project_id=$projectId");exit;}catch(Throwable $e){$error=$e->getMessage();}}
$users=db()->query('SELECT id,full_name FROM admin_users WHERE is_active=1 ORDER BY full_name')->fetchAll();$buildings=db()->prepare('SELECT id,building_name FROM construction_buildings WHERE construction_project_id=? AND is_archived=0 ORDER BY building_name');$buildings->execute([$projectId]);$buildings=$buildings->fetchAll();$companies=db()->prepare('SELECT c.id,c.company_name,pc.trade_role FROM construction_project_companies pc JOIN construction_companies c ON c.id=pc.construction_company_id WHERE pc.construction_project_id=? AND c.is_active=1 ORDER BY pc.trade_role,c.company_name');$companies->execute([$projectId]);$companies=$companies->fetchAll();
$s=db()->prepare('SELECT t.*,au.full_name assigned_name,b.building_name,c.company_name,(SELECT GROUP_CONCAT(u.full_name ORDER BY u.full_name SEPARATOR ", ") FROM construction_task_helpers h JOIN admin_users u ON u.id=h.admin_user_id WHERE h.task_id=t.id) helper_names FROM construction_tasks t LEFT JOIN admin_users au ON au.id=t.assigned_admin_user_id LEFT JOIN construction_buildings b ON b.id=t.construction_building_id LEFT JOIN construction_companies c ON c.id=t.assigned_company_id WHERE t.construction_project_id=? ORDER BY FIELD(t.status,"Open","In Progress","Complete"),t.due_date IS NULL,t.due_date,t.id DESC');$s->execute([$projectId]);$rows=$s->fetchAll();$viewId=(int)($_GET['view']??0);$comments=[];if($viewId){$c=db()->prepare('SELECT tc.*,au.full_name FROM construction_task_comments tc LEFT JOIN admin_users au ON au.id=tc.admin_user_id WHERE tc.task_id=? ORDER BY tc.created_at');$c->execute([$viewId]);$comments=$c->fetchAll();}
?><div class="page-head"><div><h1>Tasks & Walkthrough Notes</h1><p class="muted"><?=e($p['project_name'])?> · visible to all authorized project members</p></div><button class="btn btn-primary" data-open-modal="task-modal">Add Task</button></div><?php if($error):?><div class="card notice-error"><?=e($error)?></div><?php endif;?><div class="task-filters card"><button type="button" class="btn btn-secondary" data-task-filter="">All</button><button type="button" class="btn btn-secondary" data-task-filter="mine">My Tasks</button><button type="button" class="btn btn-secondary" data-task-filter="overdue">Overdue</button><button type="button" class="btn btn-secondary" data-task-filter="Complete">Completed</button></div><div class="grid task-grid" style="margin-top:18px"><?php foreach($rows as $r):$over=$r['status']!=='Complete'&&$r['due_date']&&$r['due_date']<date('Y-m-d');?><article class="card task-card <?=$over?'task-overdue':''?>" data-status="<?=e($r['status'])?>" data-assigned="<?=e((string)$r['assigned_admin_user_id'])?>" data-overdue="<?=$over?'1':'0'?>"><div class="building-card-head"><span class="badge"><?=e($r['building_name']?:'Project-Wide')?></span><span class="badge <?=e(dev_status_class($r['status']))?>"><?=e($r['status'])?></span></div><h2><?=e($r['title'])?></h2><p><?=nl2br(e($r['description']))?></p><p class="muted"><strong>Assigned:</strong> <?=e($r['assigned_name']?:$r['company_name']?:'Unassigned')?><br><?php if($r['helper_names']):?><strong>Helpers:</strong> <?=e($r['helper_names'])?><br><?php endif;?><strong>Due:</strong> <?=e(dev_date($r['due_date']))?> · <?=e($r['priority'])?></p><div class="actions"><a class="btn btn-secondary btn-small" href="tasks.php?project_id=<?=$projectId?>&view=<?=$r['id']?>">Comments</a><?php if($r['status']!=='Complete'):?><a class="btn btn-complete btn-small" href="tasks.php?project_id=<?=$projectId?>&complete=<?=$r['id']?>">Complete</a><?php else:?><a class="btn btn-secondary btn-small" href="tasks.php?project_id=<?=$projectId?>&reopen=<?=$r['id']?>">Reopen</a><?php endif;?></div><?php if($viewId===(int)$r['id']):?><div class="task-comments"><h3>Updates</h3><?php foreach($comments as $cm):?><p><strong><?=e($cm['full_name']?:'User')?></strong> <small><?=e(dev_datetime($cm['created_at']))?></small><br><?=nl2br(e($cm['comment_text']))?></p><?php endforeach;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="project_id" value="<?=$projectId?>"><input type="hidden" name="action" value="comment"><input type="hidden" name="task_id" value="<?=$r['id']?>"><textarea name="comment_text" placeholder="Add progress note..."></textarea><button class="primary">Add Update</button></form></div><?php endif;?></article><?php endforeach;?></div>
<div class="dev-modal" id="task-modal" hidden><div class="dev-modal-panel"><button class="modal-close" data-close-modal>×</button><h2>Add Task</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="project_id" value="<?=$projectId?>"><input type="hidden" name="action" value="add"><div><label>Task</label><input name="title" required></div><div><label>Building</label><select name="construction_building_id"><option value="">Project-Wide</option><?php foreach($buildings as $b):?><option value="<?=$b['id']?>"><?=e($b['building_name'])?></option><?php endforeach;?></select></div><div><label>Type</label><select name="task_type"><option>Task</option><option>Walkthrough Note</option><option>Punch Item</option><option>Safety</option><option>Delivery</option></select></div><div><label>Priority</label><select name="priority"><option>Normal</option><option>High</option><option>Critical</option></select></div><div><label>Due Date</label><input type="date" name="due_date"></div><div><label>Assign Team Member</label><select name="assigned_admin_user_id"><option value="">Unassigned</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['full_name'])?></option><?php endforeach;?></select></div><div><label>Assign Contractor</label><select name="assigned_company_id"><option value="">None</option><?php foreach($companies as $c):?><option value="<?=$c['id']?>"><?=e($c['trade_role'].' — '.$c['company_name'])?></option><?php endforeach;?></select></div><div><label>Helpers</label><select name="helper_ids[]" multiple size="4"><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['full_name'])?></option><?php endforeach;?></select></div><div class="form-full"><label>Notes / Instructions</label><textarea name="description"></textarea></div><div class="form-full"><button class="primary">Add Task</button></div></form></div></div><script>document.querySelectorAll('[data-task-filter]').forEach(b=>b.onclick=()=>{const f=b.dataset.taskFilter;document.querySelectorAll('.task-card').forEach(c=>c.hidden=f==='mine'?c.dataset.assigned!=='<?=e((string)$user['id'])?>':f==='overdue'?c.dataset.overdue!=='1':f?c.dataset.status!==f:false)})</script><?php require __DIR__.'/includes/footer.php';?>
